    @Test func timeActivityClassificationMigratesLegacyAuditAndPersistsWithoutANewModelField() throws {
        let occurredAt = Date(timeIntervalSinceReferenceDate: 75_000)
        let legacyEvent = TimeEntryReviewEvent(
            action: .submitted,
