        let dispatcher = AppUser(email: "dispatch@gunnaire.com", role: .dispatcher)
        let users = [accounting, dispatcher]

        #expect(AppAccess.visibleFieldPaymentInvoiceIDs(
            email: accounting.email,
            users: users,
            serviceCalls: [call],
            invoices: [invoice]
        ) == [invoice.id])
        #expect(AppAccess.visibleFieldPaymentInvoiceIDs(
            email: dispatcher.email,
            users: users,
            serviceCalls: [call],
            invoices: [invoice]
        ).isEmpty)
    }

