          "DocNumber": "1042",
          "CustomerRef": { "value": "QB-CUST-1", "name": "Linked QBO Customer" },
          "TotalAmt": 500,
          "Balance": 0,
          "TxnDate": "2026-08-13",
          "ShipAddr": { "Line1": "515 Imported Service Way" }
        }
