            from: Data(#"{"Id":"QBO-ITEM-CONFLICT","SyncToken":"3","Name":"Compressor Repair","Type":"NonInventory","UnitPrice":2200}"#.utf8)
        )
        #expect(throws: QuickBooksCatalogReconciliationError.self) {
